INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: easy / L2 — Net working capital calculation
(4, 'Financial Statement Analysis', 'Clearwater Electronics reports current assets of $720,000 and current liabilities of $480,000 at December 31, 2025. What is the company''s net working capital?', '["$240,000", "$1,200,000", "$480,000", "$720,000"]'::jsonb, 0, 'Net working capital equals current assets minus current liabilities (ASC 210-10-45). Clearwater''s working capital is $720,000 minus $480,000 = $240,000, indicating the company has positive short-term liquidity to cover obligations. Choice B ($1,200,000) incorrectly adds current assets and current liabilities rather than subtracting, which would dramatically overstate the company''s liquidity position.', 'easy', 2),

-- Q2: medium / L2 — Debt ratio calculation and interpretation
(4, 'Financial Statement Analysis', 'Foxworth Industries reports total assets of $5,400,000 and total stockholders'' equity of $2,160,000 at December 31, 2025. What is Foxworth''s debt ratio?', '["0.40", "0.60", "1.50", "2.50"]'::jsonb, 1, 'The debt ratio equals total liabilities divided by total assets (ASC 210-10-45). Total liabilities = $5,400,000 minus $2,160,000 = $3,240,000. Debt ratio = $3,240,000 / $5,400,000 = 0.60, meaning 60% of assets are financed by debt. Choice C (1.50) confuses the debt ratio with the debt-to-equity ratio ($3,240,000 / $2,160,000), which measures leverage differently.', 'medium', 2),

-- Q3: hard / L4 — External financing needed (EFN) calculation and evaluation
(4, 'Financial Statement Analysis', 'Ashford Manufacturing has current sales of $2,000,000, total assets of $1,600,000 (all vary with sales), spontaneous liabilities of $400,000, a 4% net profit margin, and a 50% dividend payout ratio. Management projects sales will increase to $2,500,000 next year. Using the EFN formula, what external financing does Ashford need, and what does this imply about its growth capacity?', '["$180,000 — the company can fund growth internally with retained earnings alone", "$350,000 — the company should issue equity to avoid overleveraging", "$250,000 — internally generated funds are insufficient to support the projected 25% sales growth", "$50,000 — the company needs minimal external financing due to high asset efficiency"]'::jsonb, 2, 'Under the EFN formula, EFN = (A/S)(delta-S) minus (L/S)(delta-S) minus PM x projected-S x (1 minus d). Here: (0.80)(500,000) minus (0.20)(500,000) minus 0.04 x 2,500,000 x 0.50 = $400,000 minus $100,000 minus $50,000 = $250,000. This means retained earnings cover only a fraction of the required asset growth (ASC 205-10). Choice A is wrong because $250,000 in external capital is clearly needed — internal funds alone are insufficient.', 'hard', 4),

-- Q4: easy / L1 — Definition of horizontal analysis
(4, 'Financial Statement Analysis', 'What does horizontal analysis of financial statements measure?', '["Each line item as a percentage of total assets", "Each line item as a percentage of revenue", "The relationship between two financial statement accounts at a single date", "The dollar or percentage change in line items across periods"]'::jsonb, 3, 'Horizontal analysis (trend analysis) compares financial data across multiple periods by calculating dollar or percentage changes from a base year (ASC 205-10). It identifies trends in revenue, expenses, and other line items over time to reveal improving or deteriorating performance. Choice A describes vertical analysis of a balance sheet, which expresses items as a percentage of total assets within a single period.', 'easy', 1),

-- Q5: hard / L4 — Exponential smoothing evaluation with competing alpha values
(4, 'Financial Statement Analysis', 'Whitfield Distributing uses exponential smoothing to forecast monthly sales. The previous forecast was 4,200 units, and actual demand was 4,800 units. The production manager uses alpha = 0.2, yielding a forecast of 4,320 units, but the sales director argues alpha = 0.7 would better capture the demand surge. Evaluate the sales director''s recommendation.', '["The alpha = 0.7 forecast of 4,620 units is more responsive but may overreact to random fluctuations, making it appropriate only if the demand increase reflects a genuine trend shift", "The alpha = 0.7 forecast of 4,620 units is always superior because it minimizes forecast error in volatile markets", "The alpha = 0.2 forecast of 4,320 units is always preferred because lower smoothing constants produce more accurate predictions", "The two forecasts converge to the same value after three periods regardless of alpha"]'::jsonb, 0, 'Under exponential smoothing, New Forecast = alpha(Actual) + (1 minus alpha)(Previous). At alpha = 0.7: 0.7(4,800) + 0.3(4,200) = 4,620. Higher alpha values react faster to recent changes but amplify noise from random variation (ASC 205-10 analytical guidance). The choice depends on whether the surge is structural or random. Choice B incorrectly claims higher alpha is always superior, ignoring the responsiveness-stability tradeoff.', 'hard', 4),

-- Q6: hard / L4 — Regression model fit evaluation and recommendation
(4, 'Financial Statement Analysis', 'Hartwell Manufacturing uses simple linear regression to predict quarterly maintenance costs (Y) based on machine hours (X). Results show Y = $28,000 + $9.50X with R-squared = 0.47 and a standard error of $15,200. The CFO proposes using this model to budget next quarter''s maintenance at 5,000 machine hours. Evaluate this proposal.', '["The model should not be used for budgeting because R-squared of 0.47 means machine hours explain less than half the variation in maintenance costs, indicating important variables are missing", "The model is adequate because the intercept of $28,000 confirms fixed costs are accurately captured", "The model should be accepted because any positive R-squared value indicates a statistically significant relationship", "The predicted cost of $75,500 is reliable because the regression slope coefficient is positive"]'::jsonb, 0, 'R-squared measures the proportion of variance explained by the model (AT-C 520 analytical procedures guidance). An R-squared of 0.47 means 53% of maintenance cost variation is unexplained, suggesting additional predictors such as equipment age or part costs are needed before relying on the model for budgeting. Choice C is wrong because a positive R-squared alone does not establish statistical significance — the t-statistic and p-value must be evaluated.', 'hard', 4),

-- Q7: hard / L4 — Sensitivity vs scenario analysis recommendation
(4, 'Financial Statement Analysis', 'Pendleton Corp.''s CFO is evaluating a $15 million capital expansion. The finance team has identified that projected returns depend heavily on three interconnected variables: raw material costs, foreign exchange rates, and consumer demand. The CFO asks which analytical technique would best assess the range of possible outcomes. What should the finance team recommend?', '["Sensitivity analysis, because testing one variable at a time isolates each factor''s individual impact", "Scenario analysis, because it simultaneously varies multiple correlated assumptions to model realistic best-case, base-case, and worst-case outcomes", "Regression analysis, because it quantifies the statistical relationship between variables and returns", "Exponential smoothing, because it weights recent observations more heavily to forecast variable values"]'::jsonb, 1, 'Scenario analysis changes multiple variables simultaneously to model different states of the world, making it ideal when variables are interconnected (ASC 820-10-35 fair value measurement guidance). It captures interaction effects that single-variable approaches miss. Sensitivity analysis (Choice A) changes only one variable at a time, which cannot capture the correlated interaction among raw material costs, exchange rates, and demand.', 'hard', 4),

-- Q8: easy / L2 — Payables turnover calculation
(4, 'Financial Statement Analysis', 'Marston Supply Co. reports cost of goods sold of $1,460,000 and average accounts payable of $292,000 for the year ended December 31, 2025. What is Marston''s accounts payable turnover?', '["3.0 times", "4.0 times", "5.0 times", "6.0 times"]'::jsonb, 2, 'Payables turnover equals COGS divided by average accounts payable (ASC 210-10-45). Marston''s payables turnover = $1,460,000 / $292,000 = 5.0 times, meaning the company pays its suppliers approximately five times per year on average, or roughly every 73 days. Choice A (3.0 times) likely results from dividing by an incorrect payable balance or misapplying revenue instead of COGS in the numerator.', 'easy', 2),

-- Q9: medium / L2 — Free cash flow to the firm calculation
(4, 'Financial Statement Analysis', 'Ridgeline Technologies reports operating cash flow of $890,000, capital expenditures of $340,000, and dividends paid of $150,000 for the year ended December 31, 2025. What is Ridgeline''s free cash flow to the firm (FCFF)?', '["$400,000", "$740,000", "$1,230,000", "$550,000"]'::jsonb, 3, 'Free cash flow to the firm equals operating cash flow minus capital expenditures (ASC 230-10 cash flow classification). FCFF = $890,000 minus $340,000 = $550,000. Dividends are a financing cash flow and are excluded from FCFF because they represent distributions to equity holders, not operating reinvestment. Choice A ($400,000) incorrectly subtracts dividends from FCFF, confusing free cash flow to equity (FCFE) with FCFF.', 'medium', 2),

-- Q10: medium / L2 — Weighted moving average forecast calculation
(4, 'Financial Statement Analysis', 'Oakdale Beverages uses a three-month weighted moving average to forecast demand. Weights are 50% for the most recent month, 30% for the prior month, and 20% for the oldest month. Actual sales were 8,000 units in October, 9,500 units in November, and 11,200 units in December 2025. What is the January 2026 forecast?', '["9,567 units", "9,900 units", "10,050 units", "10,450 units"]'::jsonb, 2, 'A weighted moving average assigns greater weight to more recent observations. January forecast = 0.50(11,200) + 0.30(9,500) + 0.20(8,000) = 5,600 + 2,850 + 1,600 = 10,050 units. This method captures the upward trend better than a simple average (ASC 205-10 analytical procedures). Choice A (9,567) represents the simple unweighted average of the three months, which assigns equal weight and ignores the recency effect.', 'medium', 2),

-- Q11: medium / L3 — Seasonal index deseasonalization analysis
(4, 'Financial Statement Analysis', 'Cedar Valley Apparel reports Q4 2025 actual sales of $1,380,000. The Q4 seasonal index is 1.15, reflecting holiday demand. An analyst deseasonalizes the figure to assess underlying performance. What are the deseasonalized sales, and what does the result indicate?', '["$1,200,000 — after removing seasonal effects, base-level quarterly sales are lower than the reported figure, indicating the company relies on a seasonal uplift to reach reported results", "$1,200,000 — the deseasonalized figure proves the company underperformed because actual sales should have exceeded $1,380,000", "$1,587,000 — multiplying by the seasonal index reveals stronger underlying demand than reported", "$1,380,000 — seasonal indices do not change the interpretation of actual results"]'::jsonb, 0, 'Deseasonalized value = Actual / Seasonal index = $1,380,000 / 1.15 = $1,200,000. This strips out the 15% holiday uplift to reveal the baseline quarterly run rate (ASC 205-10 trend analysis). The $1,200,000 figure represents normalized demand absent seasonal effects. Choice C incorrectly multiplies by the index, which would double-count the seasonal effect rather than removing it.', 'medium', 3),

-- Q12: easy / L2 — Degree of operating leverage (DOL) calculation
(4, 'Financial Statement Analysis', 'Briarwood Furniture reports contribution margin of $750,000 and operating income (EBIT) of $250,000 for the year ended December 31, 2025. What is Briarwood''s degree of operating leverage (DOL)?', '["2.0", "3.0", "4.0", "0.33"]'::jsonb, 1, 'Degree of operating leverage (DOL) equals contribution margin divided by EBIT. DOL = $750,000 / $250,000 = 3.0, meaning a 1% change in sales produces a 3% change in operating income due to fixed cost leverage (ASC 205-10 analytical framework). Choice D (0.33) inverts the formula by dividing EBIT by contribution margin, which dramatically understates the leverage effect.', 'easy', 2),

-- Q13: medium / L2 — Net profit margin from multi-step income statement
(4, 'Financial Statement Analysis', 'Stonebridge Consulting reports revenue of $3,200,000, cost of services of $1,920,000, selling expenses of $384,000, general and administrative expenses of $320,000, interest expense of $96,000, and income tax expense of $120,000 for the year ended December 31, 2025. What is Stonebridge''s net profit margin?', '["18.0%", "15.0%", "11.25%", "40.0%"]'::jsonb, 2, 'Net profit margin = Net income / Revenue. Net income = $3,200,000 minus $1,920,000 minus $384,000 minus $320,000 minus $96,000 minus $120,000 = $360,000. Net profit margin = $360,000 / $3,200,000 = 11.25% (ASC 220-10 comprehensive income). Choice A (18.0%) represents the operating profit margin ($576,000 / $3,200,000), which excludes interest and taxes from the calculation.', 'medium', 2),

-- Q14: medium / L3 — Working capital effect of paying a current liability
(4, 'Financial Statement Analysis', 'Redwood Manufacturing reports current assets of $900,000 and current liabilities of $600,000. On December 30, 2025, the company uses $200,000 cash to pay down a short-term bank loan. How does this transaction affect the current ratio and net working capital?', '["Current ratio decreases from 1.50 to 1.40; working capital decreases by $200,000", "Current ratio increases from 1.50 to 1.75; working capital increases by $200,000", "Current ratio and working capital both remain unchanged", "Current ratio increases from 1.50 to 1.75; working capital remains unchanged at $300,000"]'::jsonb, 3, 'Paying a current liability with cash reduces both current assets and current liabilities by $200,000 (ASC 210-10-45). New CA = $700,000, new CL = $400,000. Current ratio rises from 1.50 to 1.75 because the proportional reduction favors the ratio when it starts above 1.0. Working capital = $700,000 minus $400,000 = $300,000, unchanged. Choice A incorrectly assumes working capital decreases, missing that both components fall by equal amounts.', 'medium', 3),

-- Q15: medium / L3 — Degree of financial leverage (DFL) and earnings volatility
(4, 'Financial Statement Analysis', 'Summit Aerospace reports EBIT of $1,200,000 and interest expense of $400,000 for the year ended December 31, 2025. A competitor, Orion Defense, reports EBIT of $1,200,000 and interest expense of $100,000. What does the difference in degree of financial leverage (DFL) imply about earnings volatility?', '["Summit''s DFL of 1.50 means its EPS is less sensitive to EBIT changes than Orion''s DFL of 1.09", "Both companies have identical earnings volatility because their EBIT levels are equal", "Summit''s higher interest expense reduces its financial risk by providing a larger tax shield", "Summit''s DFL of 1.50 versus Orion''s DFL of 1.09 means a 10% decline in EBIT reduces Summit''s pretax income by 15% compared to 10.9% for Orion, indicating greater earnings volatility"]'::jsonb, 3, 'DFL = EBIT / (EBIT minus Interest). Summit: $1,200,000 / $800,000 = 1.50. Orion: $1,200,000 / $1,100,000 = 1.09. A higher DFL amplifies both gains and losses in pretax income for a given change in EBIT (ASC 470-10 debt analysis). Choice B is incorrect because equal EBIT does not mean equal earnings volatility — the capital structure determines how EBIT changes flow through to net income.', 'medium', 3),

-- Q16: easy / L1 — Common-size income statement base definition
(4, 'Financial Statement Analysis', 'On a common-size income statement, what is the base amount to which all other line items are compared?', '["Net revenue", "Total assets", "Net income", "Gross profit"]'::jsonb, 0, 'In vertical analysis of the income statement, every line item is expressed as a percentage of net revenue, enabling comparison across companies of different sizes (ASC 205-10 financial statement presentation). Revenue represents 100% and all other items are shown as a proportion thereof. Choice B (total assets) is the base for a common-size balance sheet, not the income statement.', 'easy', 1),

-- Q17: easy / L1 — Cash conversion cycle definition
(4, 'Financial Statement Analysis', 'What does the cash conversion cycle measure?', '["The number of days to collect receivables from credit customers", "The net number of days cash is tied up from inventory purchase through cash collection, minus the payment deferral from suppliers", "The total number of days it takes to sell all inventory on hand", "The average number of days between a sale and the recognition of revenue"]'::jsonb, 1, 'The cash conversion cycle (CCC) equals days inventory outstanding plus days sales outstanding minus days payable outstanding (ASC 210-10-45). It measures how long net cash is committed to the operating cycle before being recovered. Choice A describes only days sales outstanding, which is a single component of the CCC rather than the complete cycle.', 'easy', 1),

-- Q18: easy / L1 — Financial forecast vs projection distinction
(4, 'Financial Statement Analysis', 'Under AICPA standards, what distinguishes a financial forecast from a financial projection?', '["Forecasts use hypothetical assumptions; projections use expected conditions", "Forecasts are prepared by CPAs; projections are prepared by management", "Forecasts are based on expected conditions for general use; projections are based on hypothetical assumptions for limited use", "Forecasts cover one year or less; projections cover periods longer than one year"]'::jsonb, 2, 'Under AT-C Section 305, a financial forecast presents results based on the entity''s expected conditions and course of action and may be distributed for general use. A financial projection uses hypothetical what-if assumptions and is restricted to limited use by specified parties. Choice A reverses the definitions — forecasts rely on expected conditions, not hypothetical ones.', 'easy', 1),

-- Q19: easy / L1 — R-squared definition in regression analysis
(4, 'Financial Statement Analysis', 'In regression analysis, what does the coefficient of determination (R-squared) measure?', '["The slope of the regression line relative to the horizontal axis", "The number of independent variables included in the model", "The standard deviation of the residuals from the regression line", "The proportion of variation in the dependent variable explained by the independent variable or variables"]'::jsonb, 3, 'R-squared (coefficient of determination) measures the percentage of variation in the dependent variable explained by the regression model (AT-C 520 on analytical procedures). An R-squared of 0.85 means the model explains 85% of the variation with 15% unexplained. Choice C describes the standard error of the estimate, which is a separate measure of prediction accuracy around the regression line.', 'easy', 1),

-- Q20: hard / L3 — Accruals ratio and earnings quality analysis
(4, 'Financial Statement Analysis', 'Thornhill Electronics reports net income of $2,400,000 and operating cash flow of $800,000 for the year ended December 31, 2025. Average total assets are $12,000,000. The balance sheet accruals ratio is substantially positive. The analyst also observes aggressive revenue recognition timing and rising receivables relative to sales. What does the accruals ratio most likely indicate about earnings quality?', '["Earnings quality is high because net income exceeds operating cash flow, reflecting effective accrual accounting", "The accruals ratio of 13.3% signals poor earnings quality because the large gap between net income and operating cash flow suggests reported earnings may not be sustainable", "The ratio is inconclusive without comparing it to the industry average accruals ratio", "A positive accruals ratio indicates the company is effectively managing its working capital cycle"]'::jsonb, 1, 'The balance sheet accruals ratio = (NI minus OCF) / Average total assets = ($2,400,000 minus $800,000) / $12,000,000 = 13.3%. A high positive ratio combined with aggressive recognition and rising receivables suggests earnings are inflated by non-cash accruals rather than supported by cash generation (ASC 205-10). Choice A incorrectly equates accrual excess with quality, when research shows the opposite — high accruals signal lower earnings persistence.', 'hard', 3),

-- Q21: medium / L3 — Price-to-book ratio below 1.0 implications
(4, 'Financial Statement Analysis', 'Crestmont Financial has a price-to-book (P/B) ratio of 0.75 at December 31, 2025, while the banking industry average P/B is 1.20. What does Crestmont''s below-book valuation most likely indicate?', '["The company''s stock is overvalued relative to its net asset base", "The market expects the company''s future return on equity to fall below its cost of equity, implying value destruction", "The company has excessive intangible assets inflating its book value beyond recoverable amounts", "A P/B below 1.0 automatically confirms the stock is an undervalued investment opportunity"]'::jsonb, 1, 'A P/B ratio below 1.0 indicates the market values the company at less than its reported net assets (ASC 820-10 fair value concepts). This typically signals that investors expect future ROE to fall below the cost of equity, destroying rather than creating shareholder value. Choice D incorrectly assumes a low P/B automatically makes the stock undervalued, ignoring that the discount may reflect genuine fundamental deterioration rather than a market mispricing.', 'medium', 3),

-- Q22: medium / L3 — Debt service coverage ratio covenant analysis
(4, 'Financial Statement Analysis', 'Westbrook Manufacturing reports EBITDA of $1,850,000, annual debt principal payments of $600,000, and interest expense of $250,000 for the year ended December 31, 2025. The company''s lender requires a minimum debt service coverage ratio (DSCR) of 1.5x. Does Westbrook meet the covenant?', '["Yes — DSCR is 2.18x, calculated as EBITDA divided by total debt service of $850,000", "No — DSCR is 1.23x because depreciation must be subtracted from EBITDA before computing coverage", "Yes — DSCR is 7.40x, calculated as EBITDA divided by interest expense only", "No — DSCR is 0.85x because EBITDA must be divided by total outstanding liabilities"]'::jsonb, 0, 'DSCR = EBITDA / Total debt service. Total debt service = principal ($600,000) + interest ($250,000) = $850,000. DSCR = $1,850,000 / $850,000 = 2.18x, exceeding the 1.5x covenant (ASC 470-10 on debt covenants). This means Westbrook generates more than double the cash earnings needed to service its debt. Choice C incorrectly divides EBITDA by interest expense only, ignoring principal repayments that are a critical component of debt service.', 'medium', 3),

-- Q23: medium / L3 — Common-size balance sheet structural shift analysis
(4, 'Financial Statement Analysis', 'Oakmont Industries'' common-size balance sheet shows PP&E declining from 55% to 35% of total assets over three years, while intangible assets rose from 5% to 25%. Total assets increased 20% over the period. What does this structural shift most likely indicate?', '["The company is experiencing asset impairment on its physical plant and equipment", "The company''s total asset base is declining due to accelerated depreciation methods", "The shift suggests errors in the classification of assets between tangible and intangible categories", "The company is transitioning from a capital-intensive model to an acquisition-driven or knowledge-based strategy emphasizing intellectual property and goodwill"]'::jsonb, 3, 'Common-size analysis reveals structural shifts in asset composition over time (ASC 205-10 presentation). The decline in PP&E as a percentage of growing total assets combined with rising intangibles suggests investments in acquisitions, patents, or technology rather than physical plant expansion. Choice A is incorrect because impairment would reduce total assets, whereas total assets grew 20% over the period, indicating strategic reinvestment rather than asset deterioration.', 'medium', 3),

-- Q24: easy / L1 — Residual income definition
(4, 'Financial Statement Analysis', 'What does residual income measure?', '["Net income divided by average shareholders'' equity", "The dollar amount of income earned above the minimum required return on invested equity capital", "Operating income minus total depreciation expense for the period", "Cash flow from operations minus total capital expenditures"]'::jsonb, 1, 'Residual income equals net income minus an equity charge (equity multiplied by cost of equity), measuring the dollar amount earned above the minimum required return on shareholders'' capital (ASC 280-10 segment reporting). It identifies whether a division or company truly creates value beyond its capital cost. Choice A describes return on equity (ROE), which is a ratio rather than an absolute dollar measure of excess returns.', 'easy', 1),

-- Q25: medium / L2 — Simple linear regression interpretation and prediction
(4, 'Financial Statement Analysis', 'Glacier Logistics uses simple linear regression to model total shipping costs (Y) based on number of shipments (X). The regression output is Y = $42,000 + $185X with R-squared = 0.91. If Glacier processes 600 shipments next quarter, what are the predicted total shipping costs?', '["$153,000", "$111,000", "$142,200", "$185,000"]'::jsonb, 0, 'Using the regression equation, Y = $42,000 + $185(600) = $42,000 + $111,000 = $153,000. The intercept ($42,000) represents estimated fixed shipping costs per quarter, and the slope ($185) represents the variable cost per additional shipment (AT-C 520 analytical procedures). Choice B ($111,000) omits the fixed cost intercept, computing only the variable component and understating total predicted costs.', 'medium', 2),

-- Q26: medium / L2 — AT-C 305 engagement type for prospective financial statements
(4, 'Financial Statement Analysis', 'Brightwater Corp. engaged a CPA to provide assurance on its financial forecast for a bank loan application. The forecast is based on management''s expected conditions and will be distributed to multiple potential lenders. Under AT-C Section 305, which type of engagement is most appropriate?', '["Examination engagement, providing positive assurance that assumptions are reasonable", "Agreed-upon procedures engagement, limited to specific tests requested by the bank", "Compilation engagement, assembling the forecast without providing any assurance", "Audit engagement, expressing an opinion on the forecast''s fair presentation"]'::jsonb, 0, 'Under AT-C 305, a financial forecast for general distribution may be examined, providing positive assurance (an opinion) that the assumptions are reasonable and the presentation conforms to AICPA guidelines. This gives the broadest assurance appropriate for multiple users. Choice D is incorrect because CPAs cannot audit prospective financial statements — the forward-looking nature of forecasts precludes the level of evidence required for an audit opinion.', 'medium', 2),

-- Q27: hard / L4 — Evaluate CEO claim using common-size income statement trends
(4, 'Financial Statement Analysis', 'Atlas Global''s common-size income statements show the following changes over two years: COGS decreased from 58% to 52% of revenue, SG&A increased from 18% to 26%, and net profit margin declined from 12% to 9%. Revenue grew 15% over the period. The CEO claims the gross margin improvement demonstrates operational success. Evaluate this claim.', '["The CEO''s claim is valid because the 6-percentage-point gross margin improvement clearly outweighs the SG&A increase", "The claim is valid because rising revenue combined with falling COGS percentage proves greater efficiency", "The claim is misleading because the 8-percentage-point SG&A increase more than offsets the gross margin gain, producing a net decline in profitability that indicates deteriorating overall cost control", "The claim cannot be evaluated without comparing Atlas Global to industry benchmarks"]'::jsonb, 2, 'Common-size analysis reveals that while production costs improved (COGS fell 6 points), selling and administrative costs grew 8 points, driving net margin from 12% to 9% (ASC 205-10 presentation). The CEO''s selective focus on gross margin ignores the bottom-line deterioration. Choice A is wrong because overall profitability declined despite the gross margin gain — the SG&A increase more than consumed the production cost savings.', 'hard', 4),

-- Q28: medium / L2 — Leverage effect on EPS with debt vs equity financing
(4, 'Financial Statement Analysis', 'Harborview Inc. is raising $2,000,000 to fund an expansion and must choose between issuing 10% long-term debt or issuing 100,000 shares of common stock at $20 per share. Currently, Harborview has 400,000 shares outstanding, EBIT of $1,500,000, and a 25% tax rate. What is the EPS under each financing alternative?', '["Debt: $2.63; Equity: $2.44", "Debt: $2.25; Equity: $2.44", "Debt: $3.25; Equity: $3.00", "Debt: $2.44; Equity: $2.25"]'::jsonb, 3, 'Under debt financing: EBT = $1,500,000 minus $200,000 interest = $1,300,000; NI = $1,300,000 x 0.75 = $975,000; EPS = $975,000 / 400,000 = $2.44. Under equity: NI = $1,500,000 x 0.75 = $1,125,000; EPS = $1,125,000 / 500,000 = $2.25 (ASC 260-10 EPS guidance). Debt produces higher EPS because the interest tax shield reduces after-tax cost and shares remain constant. Choice B reverses the results.', 'medium', 2),

-- Q29: medium / L3 — Cash flow adequacy ratio analysis
(4, 'Financial Statement Analysis', 'Pinecrest Holdings reports operating cash flow of $2,100,000, capital expenditures of $900,000, debt principal repayments of $500,000, and dividends paid of $300,000 for the year ended December 31, 2025. An analyst computes the cash flow adequacy ratio. What does the ratio reveal about Pinecrest''s financial flexibility?', '["The ratio of 2.33 indicates strong cash generation well in excess of all capital commitments", "The ratio of 0.78 indicates the company must borrow to meet its ongoing obligations", "The ratio of 1.24 indicates Pinecrest barely covers its capital outlays, debt repayments, and dividends, leaving limited margin for unexpected needs", "The ratio cannot be calculated without also knowing the company''s net income and total debt outstanding"]'::jsonb, 2, 'Cash flow adequacy ratio = OCF / (CapEx + Debt repayments + Dividends) = $2,100,000 / ($900,000 + $500,000 + $300,000) = $2,100,000 / $1,700,000 = 1.24 (ASC 230-10 cash flow analysis). A ratio above 1.0 means obligations are covered, but 1.24 provides only a thin buffer for unexpected needs. Choice A (2.33) incorrectly divides OCF by capital expenditures alone, overstating coverage by ignoring debt service and dividends.', 'medium', 3),

-- Q30: medium / L3 — Asset turnover decline from expansion investment
(4, 'Financial Statement Analysis', 'Meridian Retail''s asset turnover declined from 2.4 to 1.8 over two years, while revenue grew 10%. The company opened five new stores and invested $8 million in leasehold improvements during the period. What does the decline in asset turnover most likely indicate about the expansion strategy?', '["Revenue growth was too slow, indicating declining customer demand across all locations", "The new store investments increased the asset base faster than the revenue they generated, temporarily depressing turnover as the locations ramp up", "The company should immediately divest the new stores to restore its prior turnover ratio", "The decline proves the expansion will not be profitable in the long run"]'::jsonb, 1, 'Asset turnover = Revenue / Average total assets. When a company invests heavily in expansion, the denominator grows immediately while new-store revenue builds gradually over time, causing a temporary decline in asset turnover (ASC 360-10 long-lived assets). This is expected and typically reverses as locations mature. Choice A is incorrect because revenue grew 10% overall, indicating demand is not declining — the ratio decline is driven by the faster growth in the asset base.', 'medium', 3)
;

COMMIT;
